_ANSWERS = sorted(set(_ANSWERS) - set('ABUSE ADULT BIBLE CHINA CRUDE DEMON DEVIL FATAL FRAUD GUILT HIPPO INTEL NASTY OBESE OVARY PADDY RIFLE SHOOT SHREW SOBER TABOO TIBIA TIPSY TOXIC TOXIN TRAMP TRUMP TUBAL TUMOR URINE VAPID VENOM VIRUS VODKA VOMIT WELCH WELSH WILLY WITCH'.split()))
assert all(len(w)==5 and w.isascii() and w.isalpha() for w in _ANSWERS)
random.Random(20261116).shuffle(_ANSWERS)
_GUESSES = frozenset((Path(__file__).with_name('daily_word_guesses.txt')).read_text(encoding='utf-8').split()) | frozenset(_ANSWERS)


def db_path():
    override = os.environ.get('ELITE_DAILY_WORD_DB')
    if override:
        return Path(override)
    if Path('/var/data').is_dir():
        return Path('/var/data/elite_daily_word.sqlite3')
    return Path(os.environ.get('LOCALAPPDATA') or Path.home()) / 'EliteNetwork' / 'elite_daily_word.sqlite3'


def connect():
    path = db_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    db = sqlite3.connect(str(path), timeout=5, isolation_level=None)
    db.execute('CREATE TABLE IF NOT EXISTS daily_word (day TEXT NOT NULL, player TEXT NOT NULL, guesses TEXT NOT NULL, status TEXT NOT NULL, PRIMARY KEY(day,player))')
    return db


def puzzle_day(now):
    """Network day changes at 11 AM local, even after midnight."""
    return (now.date() - timedelta(days=int(now.hour < 11))).isoformat()


def answer_for(day):
    return _ANSWERS[(date.fromisoformat(day) - date(2026, 11, 16)).days % len(_ANSWERS)]


def grade(answer, guess):
    remaining = list(answer)
    marks = ['absent'] * 5
    for i, letter in enumerate(guess):
        if letter == answer[i]:
            marks[i] = 'correct'
            remaining[i] = None
    for i, letter in enumerate(guess):
        if marks[i] != 'correct' and letter in remaining:
            marks[i] = 'present'
            remaining[remaining.index(letter)] = None
    return marks


_POINTS = (100, 80, 60, 40, 20, 10)


def score_for(status, attempts):
    return _POINTS[attempts - 1] if status == 'won' and 1 <= attempts <= 6 else 0


def player_stats(db, player, day):
    # Derive totals from one saved result per puzzle day; no duplicate awards,
    # no new table, and no future simulation dates included in today's stats.
    rows = db.execute(
        "SELECT day, guesses, status FROM daily_word WHERE player=? AND day<=? "
        "AND status IN ('won','lost') ORDER BY day", (player, day)
    ).fetchall()
    solved = points = best = run = 0
    last_win = None
    for saved_day, raw_guesses, status in rows:
        if status != 'won':
            run = 0
            last_win = None
            continue
        solved += 1
        points += score_for(status, len(json.loads(raw_guesses)))
        win_day = date.fromisoformat(saved_day)
        run = run + 1 if last_win is not None and win_day == last_win + timedelta(days=1) else 1
        last_win = win_day
        best = max(best, run)
    today = date.fromisoformat(day)
    current = run if last_win in (today, today - timedelta(days=1)) else 0
    played = len(rows)
    return {'played': played, 'solved': solved, 'total_points': points,
            'win_rate': round(100 * solved / played) if played else 0,
            'streak': current, 'best_streak': best}


def view(day, guesses, status):
    data = {'day':day, 'guesses':[{'word':w, 'marks':grade(answer_for(day),w)} for w in guesses], 'status':status, 'max_attempts':6, 'first_letter':answer_for(day)[0]}
    if status in ('won','lost'):
        data['answer'] = answer_for(day)
        data['points'] = score_for(status, len(guesses))
    return data


def play(now, payload):
    if not isinstance(payload, dict):
        raise ValueError('Invalid request.')
    raw_token = payload.get('token')
    if not isinstance(raw_token,str) or not re.fullmatch(r'[a-f0-9]{32}',raw_token):
        raise ValueError('Invalid player token.')
    player = hashlib.sha256(raw_token.encode()).hexdigest()
    day = puzzle_day(now)
    action = payload.get('action')
    if action not in ('status','start','guess'):
        raise ValueError('Invalid action.')
    with closing(connect()) as db:
        db.execute('BEGIN IMMEDIATE')
        try:
            row = db.execute('SELECT guesses,status FROM daily_word WHERE day=? AND player=?',(day,player)).fetchone()
            guesses, status = (json.loads(row[0]),row[1]) if row else ([], 'new')
            if action == 'start' and not row:
                status = 'playing'
                db.execute('INSERT INTO daily_word VALUES (?,?,?,?)',(day,player,'[]',status))
            elif action == 'guess':
                if payload.get('day') != day:
                    raise ValueError('A new puzzle is available. Reload the page to start.')
                if not row:
                    raise ValueError('Start your puzzle first.')
                # Idempotent retry / stale tab: return saved state instead of consuming another guess.
                if status == 'playing' and payload.get('attempt') == len(guesses):
                    raw = payload.get('guess')
                    word = raw.strip().upper() if isinstance(raw,str) else ''
                    if not re.fullmatch(r'[A-Z]{5}',word) or word not in _GUESSES:
                        raise ValueError('Enter a valid five-letter word.')
                    if word[0] != answer_for(day)[0]:
                        raise ValueError('Your guess must start with ' + answer_for(day)[0] + '.')
                    if word in guesses:
                        raise ValueError('You already tried that word.')
                    guesses.append(word)
                    status = 'won' if word == answer_for(day) else ('lost' if len(guesses)==6 else 'playing')
                    db.execute('UPDATE daily_word SET guesses=?,status=? WHERE day=? AND player=?',(json.dumps(guesses),status,day,player))
            stats = player_stats(db, player, day)
            db.execute('COMMIT')
        except Exception:
            db.execute('ROLLBACK')
            raise
    result = view(day,guesses,status)
    result['stats'] = stats
    return result


def counts(now):
    day = puzzle_day(now)
    with closing(connect()) as db:
        rows = db.execute('SELECT status,COUNT(*) FROM daily_word WHERE day=? GROUP BY status',(day,)).fetchall()
    tally = dict(rows)
    return {'day':day,'started':sum(tally.values()),'completed':tally.get('won',0)+tally.get('lost',0),'solved':tally.get('won',0)}
